  actor: Actor,
  orgId: OrgId,
  userId: import("@/types/common").UserId,
): Promise<void> {
  const member = await (await import("@/server/repositories/member-repository")).findMember(orgId, userId);
  if (member) {
    if (member.status !== "active") throw new NotFoundError("Member", userId);
    return;
